1	package nettrace
2	
3	import (
4		"fmt"
5		"go/ast"
6		"go/parser"
7		"go/token"
8		"os"
9		"strconv"
10		"strings"
11		"testing"
12	)
13	
14	// The trace sends its probes itself, over ICMP and UDP sockets. It must never
15	// start a child process (traceroute, ping) nor replace the process image, on
16	// any platform. The guard reads every .go file of the package whatever its
17	// build constraints (go/parser does not evaluate them), so a file that only
18	// builds on another OS is covered too.
19	
20	// bannedImports are packages that must not be imported at all.
21	var bannedImports = map[string]bool{
22		"os/exec":                  true,
23		"golang.org/x/sys/execabs": true,
24	}
25	
26	// dotWatched are packages that must not be dot-imported: a dot-import hides
27	// the package name the selector check relies on.
28	var dotWatched = map[string]bool{
29		"os":                    true,
30		"syscall":               true,
31		"os/exec":               true,
32		"golang.org/x/sys/unix": true,
33	}
34	
35	// bannedSymbols maps an import path to the process-launching symbols it must
36	// not expose here, called or not (`f := os.StartProcess` is caught too). The
37	// socket symbols the engine needs (Recvmsg, Setsockopt...) stay allowed.
38	var bannedSymbols = map[string]map[string]bool{
